"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$containerName = '"'rawsqlhost09135b017eaa4572beaba555c1a949a2'
"'$existing = docker ps -a --filter "name=''^/$containerName$" --format '"'{{.Names}}'
if ("'$existing) { throw "Container name already exists: $existing" }
docker run --detach --name $containerName --label '"'rawsql-host-runner=09135b017eaa4572beaba555c1a949a2' --env 'POSTGRES_PASSWORD=candidate-probe-password' --publish '64701:5432' postgres:16
if ("'$LASTEXITCODE -ne 0) { throw '"'Failed to start PostgreSQL container.' }
"'$ready = $false
for ($attempt = 1; $attempt -le 60; $attempt++) {
  docker exec $containerName pg_isready -U postgres -d postgres | Out-Null
  if ($LASTEXITCODE -eq 0) { $ready = $true; break }
  Start-Sleep -Seconds 1
}
if (-not $ready) { throw '"'PostgreSQL did not become ready within 60 seconds.' }
Write-Output 'PostgreSQL is ready.'"

