"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$containerName = '"'rawsqlhost09135b017eaa4572beaba555c1a949a2'
docker exec "'$containerName psql -U postgres -d postgres -v ON_ERROR_STOP=1 -c '"'CREATE TABLE candidate_probe(id int primary key,note text);'
if ("'$LASTEXITCODE -ne 0) { throw '"'Failed to create candidate_probe.' }
