"'$deadline = (Get-Date).AddSeconds(180)
while ((Get-Date) -lt $deadline) {
  if (Test-Path -LiteralPath $verifiedFile -PathType Leaf) {
    Write-Output '"'Parent verification marker detected.'
    exit 0
  }
  Start-Sleep -Seconds 2
}
