"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$containerName = '"'rawsqlhost09135b017eaa4572beaba555c1a949a2'
"'$expectedLabel = '"'09135b017eaa4572beaba555c1a949a2'
"'$actualLabel = docker inspect --format '"'{{ index .Config.Labels \"rawsql-host-runner\" }}' "'$containerName
if ($LASTEXITCODE -ne 0) { throw '"'Cannot inspect expected container.' }
if ("'$actualLabel.Trim() -ne $expectedLabel) { throw "Refusing cleanup: unexpected label '"'"'$actualLabel'"'.\" }
docker stop "'$containerName
if ($LASTEXITCODE -ne 0) { throw '"'Failed to stop expected container.' }
docker rm "'$containerName
if ($LASTEXITCODE -ne 0) { throw '"'Failed to remove expected container.' }
"'$remaining = docker ps -a --filter "name=''^/$containerName$" --format '"'{{.Names}}'
if ("'$remaining) { throw '"'Expected container still exists after cleanup.' }
Write-Output 'Specified container stopped and removed.'"

